ee:message.ee:set-payload:
%dw 2.0
output text/xml
ns S http://schemas.xmlsoap.org/soap/envelope/
ns ser http://soap.sforce.com/schemas/class/ServiciosSAAW
---
{
S#Envelope: {
   S#Header: {
      ser#SessionHeader: {
         ser#sessionId: vars.token_response.access_token
      }
   },
   S#Body: {
      ser#ajuste_saaw: {
         ser#ajuste: {
            ser#fechaDelAjuste: payload.AjusteSAAWRequest.ajuste_saaw.ajuste.fechaDelAjuste,
            ser#noDelAjuste: payload.AjusteSAAWRequest.ajuste_saaw.ajuste.noDelAjuste,
            ser#numeroCaso: vars.numeroCaso,
            ser#valorAjustado: payload.AjusteSAAWRequest.ajuste_saaw.ajuste.valorAjustado
         }
      }
   }
}
}
